SELECT 
FROM SYS_QUERY_TEMPLATE


        AND TEMPLATE_NAME LIKE CONCAT('%', #{queryVO.templateName}, '%')


        AND TEMPLATE_TYPE = #{queryVO.templateType}


        AND ENABLED = #{queryVO.enabled}


        AND IS_PUBLIC = #{queryVO.isPublic}


        AND CREATE_BY = #{queryVO.createBy}


ORDER BY CREATE_TIME DESC

SELECT 
FROM SYS_QUERY_TEMPLATE
WHERE TEMPLATE_NAME = #{templateName}

    AND TEMPLATE_ID != #{excludeId}

LIMIT 1

SELECT 
FROM SYS_QUERY_TEMPLATE


        AND TEMPLATE_NAME LIKE CONCAT('%', #{templateName}, '%')


        AND TEMPLATE_TYPE = #{templateType}


        AND ENABLED = #{enabled}


        AND IS_PUBLIC = #{isPublic}


        AND CREATE_BY = #{createBy}


ORDER BY CREATE_TIME DESC
